INSERT INTO `homepage_sections` VALUES (1,'hero','Temukan Hunian Impian Keluarga Modern & Asri','Kawasan hunian eksklusif dengan fasilitas lengkap, lingkungan hijau, keamanan 24 jam, dan akses cepat menuju jalan tol & stasiun utama.',1,1,'full_image','{\"badge_text\":\"Developer Properti Terpercaya & Legalitas Aman (SHM)\",\"btn1_text\":\"Jelajahi Tipe Rumah\",\"btn1_link\":\"properti\",\"btn2_text\":\"Hitung Simulasi KPR\",\"btn2_link\":\"kpr-calculator\",\"stat1_value\":\"100%\",\"stat1_label\":\"Sertifikat SHM\",\"stat2_value\":\"DP 0%\",\"stat2_label\":\"Promo Cicilan KPR\",\"stat3_value\":\"24\\/7\",\"stat3_label\":\"Keamanan & CCTV\",\"media_type\":\"image\",\"image_url\":\"https:\\/\\/images.unsplash.com\\/photo-1600585154340-be6161a56a0c?w=900&auto=format&fit=crop&q=80\",\"focal_x\":\"center\",\"focal_y\":\"center\",\"aspect_ratio\":\"4\\/3\",\"price_badge_prefix\":\"Harga Mulai Dari\",\"price_badge_text\":\"Rp 650 Juta-an\",\"video_source\":\"youtube\",\"video_url\":\"\",\"video_poster\":\"\"}','2026-09-20 18:45:56','2026-09-21 02:07:12'),(2,'properties','Tipe Rumah & Klaster Unggulan','Pilihan Unit Terbaik',1,2,'3_col','{\"limit\":6,\"btn_text\":\"Lihat Semua Tipe\",\"btn_link\":\"properti\",\"show_filter\":0}','2026-09-20 18:45:56','2026-09-20 18:45:56'),(3,'about','Membangun Harmoni dan Kualitas Hidup Lebih Baik','Tentang Pengembang & Visi Kawasan',1,3,'centered','{\"description\":\"Grand Harmoni Residence menghadirkan kawasan hunian berstandar tinggi yang menggabungkan keselarasan alam dengan infrastruktur modern, memberikan nilai investasi tinggi dan kenyamanan sejati bagi setiap keluarga.\",\"highlight_1\":\"Konstruksi bangunan terstandarisasi mutu SNI dengan pondasi kokoh.\",\"highlight_2\":\"Sistem kabel dan utilitas bawah tanah (underground utilities) rapi dan modern.\",\"highlight_3\":\"Aksesibilitas prima hanya beberapa menit ke fasilitas publik dan jalur transportasi utama.\",\"image_url\":\"https:\\/\\/images.unsplash.com\\/photo-1545324418-cc1a3fa10c00?w=900&auto=format&fit=crop&q=80\",\"focal_x\":\"center\",\"focal_y\":\"center\",\"experience\":\"15+ Tahun\",\"exp_label\":\"Pengalaman Membangun Hunian Berkualitas\"}','2026-09-20 18:45:56','2026-09-21 02:04:55'),(4,'features','Kenyamanan & Nilai Investasi Terbaik','Mengapa Memilih Kami',1,4,'grid_4','{\"intro\":\"Dirancang dengan standar konstruksi tinggi dan tata ruang lingkungan terpadu.\",\"items\":[{\"icon\":\"bi-shield-check\",\"title\":\"Legalitas 100% Aman\",\"desc\":\"Sertifikat Hak Milik (SHM) dan IMB\\/PBG sudah pecah per unit, siap akad notaris.\"},{\"icon\":\"bi-geo-alt-fill\",\"title\":\"Lokasi Sangat Strategis\",\"desc\":\"Hanya 10 menit ke gerbang tol, pusat perbelanjaan, sekolah favorit, dan rumah sakit.\"},{\"icon\":\"bi-tree-fill\",\"title\":\"Eco Green Living\",\"desc\":\"Dilengkapi taman bermain tematik, jogging track, saluran underground, dan clubhouse eksklusif.\"},{\"icon\":\"bi-cash-coin\",\"title\":\"Kemudahan KPR\",\"desc\":\"Bekerjasama dengan lebih dari 10 bank BUMN & Swasta nasional dengan proses approval cepat.\"}]}','2026-09-20 18:45:56','2026-09-20 18:45:56'),(5,'gallery','Potret Kawasan & Fasilitas Hunian','Galeri Lingkungan & Desain Interior',1,5,'masonry','{\"items\":[{\"image\":\"https:\\/\\/images.unsplash.com\\/photo-1600585154340-be6161a56a0c?w=800&auto=format&fit=crop&q=80\",\"caption\":\"Fasad Rumah Modern Tropis\",\"tag\":\"Eksterior\"},{\"image\":\"https:\\/\\/images.unsplash.com\\/photo-1600565193348-f74bd3c7ccdf?w=800&auto=format&fit=crop&q=80\",\"caption\":\"Ruang Keluarga Lapang & Sejuk\",\"tag\":\"Interior\"},{\"image\":\"https:\\/\\/images.unsplash.com\\/photo-1600607687939-ce8a6c25118c?w=800&auto=format&fit=crop&q=80\",\"caption\":\"Dapur & Ruang Makan Minimalis\",\"tag\":\"Interior\"},{\"image\":\"https:\\/\\/images.unsplash.com\\/photo-1512917774080-9991f1c4c750?w=800&auto=format&fit=crop&q=80\",\"caption\":\"Clubhouse & Kolam Renang Warga\",\"tag\":\"Fasilitas\"},{\"image\":\"https:\\/\\/images.unsplash.com\\/photo-1570129477492-45c003edd2be?w=800&auto=format&fit=crop&q=80\",\"caption\":\"Taman Hijau & Jalur Jogging Asri\",\"tag\":\"Fasilitas\"},{\"image\":\"https:\\/\\/images.unsplash.com\\/photo-1613490493576-7fde63acd811?w=800&auto=format&fit=crop&q=80\",\"caption\":\"Balkon Atas Menatap Sunset\",\"tag\":\"Eksterior\"}]}','2026-09-20 18:45:56','2026-09-20 18:45:56'),(6,'siteplan','Pilih Posisi Kavling Impian Anda','Masterplan Interaktif & Ketersediaan Unit',1,6,'interactive','{\"btn_text\":\"Buka Denah Masterplan Lengkap\",\"btn_link\":\"siteplan\",\"description\":\"Klik pada nomor kavling untuk mengecek status ketersediaan unit, blok kavling, dan spesifikasi rumah secara interaktif.\"}','2026-09-20 18:45:56','2026-09-20 18:45:56'),(7,'promo','Promo Grand Launching & Subsidi Akad','Penawaran Terbatas Bulan Ini',1,7,'banner_card','{\"badge\":\"KUOTA TERBATAS 10 UNIT PERTAMA\",\"desc\":\"Dapatkan Free DP 0%, Subsidi Biaya KPR up to 50 Juta, Bebas Biaya BPHTB & Notaris, serta bonus Smart Home System lengkap.\",\"btn_text\":\"Klaim Promo via WhatsApp\",\"image_url\":\"https:\\/\\/images.unsplash.com\\/photo-1580587771525-78b9dba3b914?w=800&auto=format&fit=crop&q=60\",\"focal_x\":\"center\",\"focal_y\":\"center\"}','2026-09-20 18:45:56','2026-09-20 18:45:56'),(8,'cta','Siap Memiliki Rumah Impian Anda Hari Ini?','Konsultasikan Kebutuhan Hunian Anda',1,8,'center','{\"desc\":\"Konsultasikan kebutuhan hunian, simulasi KPR gratis, dan jadwalkan kunjungan show unit bersama konsultan properti kami.\",\"btn1_text\":\"Jadwalkan Survey Lokasi\",\"btn1_type\":\"whatsapp\",\"btn2_text\":\"Unduh E-Katalog PDF\",\"btn2_link\":\"brochure\\/download-global\",\"bg_type\":\"image\",\"bg_image\":\"https:\\/\\/images.unsplash.com\\/photo-1600585154340-be6161a56a0c?w=1600&auto=format&fit=crop&q=80\",\"bg_video\":\"\",\"styling\":{\"bg_type\":\"default\",\"bg_color\":\"#ffffff\",\"gradient_from\":\"#1e3a8a\",\"gradient_to\":\"#0d9488\",\"gradient_angle\":\"135deg\",\"text_mode\":\"auto\",\"custom_title_color\":\"#ffffff\",\"custom_text_color\":\"#e2e8f0\",\"font_family\":\"default\",\"title_font_weight\":\"default\",\"title_transform\":\"default\",\"text_shadow\":\"none\",\"overlay_opacity\":\"default\",\"border_radius\":\"default\"}}','2026-09-20 18:45:56','2026-09-21 08:55:51');
