INSERT INTO `pages` VALUES (1,'Grand Harmoni Residence - Hunian Modern & Asri','home','Grand Harmoni Residence - Hunian Modern & Asri','Kawasan perumahan modern tropis bebas banjir dengan fasilitas lengkap dan keamanan 24 jam.','{\"time\": 1787295555000, \"blocks\": [{\"id\": \"hero-block-01\", \"data\": {\"title\": \"Hunian Modern, Asri &amp; Strategis untuk Masa Depan Keluarga\", \"subtitle\": \"Kawasan hunian eksklusif dengan fasilitas lengkap, akses tol langsung, bebas banjir, serta sistem keamanan 24 jam untuk kenyamanan hidup Anda.\", \"image_url\": \"http://localhost:8080/uploads/house_photos/type120_fasad.svg\", \"video_url\": \"https://assets.mixkit.co/videos/preview/mixkit-modern-suburban-houses-in-a-neighborhood-41445-large.mp4\", \"badge_text\": \"Kawasan Smart Green Living Residence\", \"poster_url\": \"http://localhost:8080/uploads/house_photos/type120_fasad.svg\", \"cta_chat_text\": \"Tanya Asisten AI\", \"background_type\": \"video\", \"cta_siteplan_text\": \"Buka Interactive Siteplan\"}, \"type\": \"hero\"}, {\"id\": \"features-block-01\", \"data\": {\"items\": [{\"desc\": \"Sistem gerbang tunggal dengan kartu akses RFID, pos penjagaan 24 jam, dan pemantauan CCTV di seluruh kawasan.\", \"icon\": \"fa-shield-virus\", \"title\": \"Keamanan 24 Jam &amp; One Gate\"}, {\"desc\": \"Clubhouse eksklusif warga yang dilengkapi swimming pool untuk dewasa &amp; anak, serta ruang serbaguna.\", \"icon\": \"fa-water-ladder\", \"title\": \"Clubhouse &amp; Kolam Renang\"}, {\"desc\": \"Area terbuka hijau dengan pepohonan rindang, taman bermain ramah anak, dan lintasan jogging yang nyaman.\", \"icon\": \"fa-tree\", \"title\": \"Taman Hijau &amp; Jogging Track\"}], \"title\": \"Kenyamanan Eksklusif untuk Keluarga\", \"subtitle\": \"Fasilitas modern terintegrasi untuk menunjang kenyamanan, keamanan, dan gaya hidup sehat Anda.\"}, \"type\": \"feature_grid\"}, {\"id\": \"catalog-block-01\", \"data\": {\"title\": \"Pilihan Tipe Rumah Terbaik\", \"subtitle\": \"Desain arsitektur modern tropis dengan tata ruang fungsional, pencahayaan alami maksimal, dan sirkulasi udara sejuk.\"}, \"type\": \"house_catalog\"}, {\"id\": \"cta-block-01\", \"data\": {\"desc\": \"Dapatkan simulasi KPR akurat 100% dengan algoritma anuitas perbankan dan jadwalkan kunjungan survey lokasi bersama asisten AI kami.\", \"title\": \"Konsultasikan Hunian Idaman Anda Hari Ini\", \"btn_text\": \"Mulai Konsultasi dengan AI Bot\"}, \"type\": \"cta_banner\"}]}',1,'2026-08-21 06:59:15','2026-08-21 06:59:15',NULL);
/*!40000 ALTER TABLE `pages` ENABLE KEYS */;
UNLOCK TABLES;

