INSERT INTO `settings` VALUES (1,'company_name','Pablo','2026-08-21 19:09:38','2026-09-21 10:02:54'),(2,'company_tagline','Hunian Mewah, Asri, dan Strategis untuk Keluarga Idaman','2026-08-21 19:09:38','2026-09-21 10:02:54'),(3,'company_address','Jl. Boulevard Raya No. 88, Grand City, Jakarta Barat','2026-08-21 19:09:38','2026-09-21 10:02:54'),(4,'company_phone','021-5558989','2026-08-21 19:09:38','2026-09-21 10:02:54'),(5,'company_whatsapp','6281234567890','2026-08-21 19:09:38','2026-09-21 10:02:54'),(6,'company_email','marketing@grandharmoni.co.id','2026-08-21 19:09:38','2026-09-21 10:02:54'),(7,'company_about','Grand Harmoni Residence merupakan pengembang properti terkemuka yang menghadirkan hunian modern berwawasan lingkungan hijau dengan fasilitas eksklusif seperti clubhouse, security 24 jam CCTV, underground utilities, dan akses transportasi strategis.','2026-08-21 19:09:38','2026-09-21 10:02:54'),(8,'primary_color','#1b4332','2026-08-21 19:09:38','2026-09-21 10:02:54'),(9,'secondary_color','#bc6c25','2026-08-21 19:09:38','2026-09-21 10:02:54'),(10,'promo_modal_active','1','2026-08-21 19:09:38','2026-09-21 10:02:54'),(11,'promo_modal_title','Promo Grand Launching Cluster Lavender!','2026-08-21 19:09:38','2026-09-21 10:02:54'),(12,'promo_modal_image','https://images.unsplash.com/photo-1580587771525-78b9dba3b914?w=800&auto=format&fit=crop&q=60','2026-08-21 19:09:38','2026-09-21 10:02:54'),(13,'promo_modal_desc','Dapatkan Free DP 0%, Subsidi KPR up to 50 Juta, Free Biaya BPHTB & Notaris, serta Smart Home System untuk 10 Pembeli Pertama bulan ini!','2026-08-21 19:09:38','2026-09-21 10:02:54'),(14,'promo_modal_btn_text','Klaim Promo Sekarang via WA','2026-08-21 19:09:38','2026-09-21 10:02:54'),(15,'va_name','Sarah - Konsultan Properti','2026-08-21 19:09:38','2026-09-21 10:02:54'),(16,'va_phone','6281234567890','2026-08-21 19:09:38','2026-09-21 10:02:54'),(17,'global_brochure_pdf','1787553662_28d7bbcd6e2ca6c34cc3.pdf','2026-08-21 19:09:38','2026-08-24 06:41:02'),(18